export interface EvidenceCommandIdentity {
  executable: string;
  args: string[];
}

function parseEvidenceTimeoutOverride(value: unknown): EvidenceCommandTimeoutOverrideConfig | null {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return null;
  const row = value as Record<string, unknown>;
  const keys = Object.keys(row).sort();
  if (keys.join('\0') !== ['args', 'command', 'timeoutMs'].join('\0')) return null;
  if (
    typeof row.command !== 'string'
    || row.command.length === 0
    || row.command.trim() !== row.command
    || /\s/.test(row.command)
    || !VERIFICATION_COMMAND_EXECUTABLE_ALLOWLIST.has(row.command)
  ) return null;
  if (!Array.isArray(row.args) || !row.args.every(arg => typeof arg === 'string')) return null;
  if (
    typeof row.timeoutMs !== 'number'
    || !Number.isSafeInteger(row.timeoutMs)
    || row.timeoutMs <= 0
    || row.timeoutMs > MAX_NODE_TIMER_DELAY_MS
  ) return null;
  return {
    command: row.command,
    args: [...row.args] as string[],
    timeoutMs: row.timeoutMs,
  };
}

/**
 * Resolve an evidence-only timeout override by exact parsed executable and
 * ordered argv identity. The complete override collection is one policy unit:
 * malformed rows or duplicate identities fail closed to the bounded default.
 * This never registers a routine validation command and never weakens the
 * outer abort/deadline, which {@link runValidationCommand} still caps first.
 */
export function resolveEvidenceCommandTimeoutMs(
  identity: EvidenceCommandIdentity,
  overrides: unknown,
  defaultMs: number = DEFAULT_VALIDATE_COMMAND_TIMEOUT_MS,
): number {
  const boundedDefault = Math.max(1, Math.min(MAX_NODE_TIMER_DELAY_MS, Math.floor(defaultMs)));
  if (!Array.isArray(overrides)) return boundedDefault;

  const parsed: EvidenceCommandTimeoutOverrideConfig[] = [];
  const identities = new Set<string>();
  for (const value of overrides) {
    const row = parseEvidenceTimeoutOverride(value);
    if (!row) return boundedDefault;
    const key = JSON.stringify([row.command, row.args]);
    if (identities.has(key)) return boundedDefault;
    identities.add(key);
    parsed.push(row);
  }

  const match = parsed.find(row => (
    row.command === identity.executable
    && row.args.length === identity.args.length
    && row.args.every((arg, index) => arg === identity.args[index])
  ));
  return match?.timeoutMs ?? boundedDefault;
}

/**
 * B-ec67: tokenize a pinned command string into executable + argv WITHOUT a shell.
 * Supports single/double quotes and backslash escapes so a command like
 * `node -e "console.log('MARKER_OK')"` yields ['node','-e',"console.log('MARKER_OK')"].
 * Throws on an unterminated quote. No shell metacharacter interpretation happens.
 */
export function tokenizeCommandString(command: string): string[] {
  const tokens: string[] = [];
  let current = '';
  let hasToken = false;
  let inSingle = false;
  let inDouble = false;
  for (let i = 0; i < command.length; i++) {
    const ch = command[i];
    if (inSingle) {
      if (ch === "'") inSingle = false;
      else current += ch;
      continue;
    }
    if (inDouble) {
      if (ch === '"') inDouble = false;
      else if (ch === '\\' && i + 1 < command.length && (command[i + 1] === '"' || command[i + 1] === '\\')) current += command[++i];
      else current += ch;
      continue;
    }
    if (ch === "'") { inSingle = true; hasToken = true; continue; }
    if (ch === '"') { inDouble = true; hasToken = true; continue; }
    if (ch === '\\' && i + 1 < command.length) { current += command[++i]; hasToken = true; continue; }
    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
      if (hasToken) { tokens.push(current); current = ''; hasToken = false; }
      continue;
    }
    current += ch;
    hasToken = true;
  }
  if (inSingle || inDouble) throw new Error(`verification command has an unterminated quote: ${command}`);
  if (hasToken) tokens.push(current);
  return tokens;
}

/**
 * B-ec67: parse + allowlist-check a pinned command string. Throws when empty or when
 * the leading executable is not in {@link VERIFICATION_COMMAND_EXECUTABLE_ALLOWLIST}.
 */
export function parseAllowlistedCommand(command: string): { executable: string; args: string[] } {
  const tokens = tokenizeCommandString(command);
  if (tokens.length === 0) throw new Error('verification command is empty');
  const [executable, ...args] = tokens;
  if (!VERIFICATION_COMMAND_EXECUTABLE_ALLOWLIST.has(executable)) {
    throw new Error(
      `verification command executable "${executable}" is not allowlisted ` +
      `(allowed: ${[...VERIFICATION_COMMAND_EXECUTABLE_ALLOWLIST].join(', ')}); ` +
      'a pinned verification command must be executable+argv, never a raw shell program [verification_command_not_allowlisted]',
    );
  }
  return { executable, args };
}

export interface SingleCommandExecutionResult {
  executable: string;
  args: string[];
  code: number;
  output: string;
  timedOut: boolean;
  durationMs: number;
}

export interface SingleCommandExecutionOptions extends RunValidationCommandOptions {
  cwd?: string;
  timeoutMs?: number;
}

/**
 * B-ec67: run ONE allowlisted pinned command via the shared {@link runValidationCommand}
 * spawn path (per-command timeout, output capture, no shell on POSIX). Used by the
 * evidence-write handler to derive a tool-owned receipt from the actual exit + output.
 */
export async function runSingleAllowlistedCommand(
  command: string,
  projectRoot: string,
  options: SingleCommandExecutionOptions = {},
): Promise<SingleCommandExecutionResult> {
  const { executable, args } = parseAllowlistedCommand(command);
  const { cwd, timeoutMs, ...runOptions } = options;
  const configuredTimeoutMs = timeoutMs ?? resolveEvidenceCommandTimeoutMs(
    { executable, args },
    loadConfig(projectRoot).validate?.evidenceCommandTimeoutOverrides,
  );
  const validationCommand: ValidationCommand = {
    label: 'verification-evidence-command',
    command: executable,
    args,
    ...(cwd ? { cwd } : {}),
    timeoutMs: configuredTimeoutMs,
  };
  const result = await runValidationCommand(
    validationCommand,
    projectRoot,
    DEFAULT_VALIDATE_COMMAND_TIMEOUT_MS,
    runOptions,
  );
  if (runOptions.abortSignal?.aborted) {
    throw runOptions.abortSignal.reason instanceof Error
      ? runOptions.abortSignal.reason
      : new Error('verification evidence command aborted');
  }
  if (
    result.timedOut
    && typeof runOptions.deadlineAt === 'number'
    && Date.now() >= runOptions.deadlineAt
  ) {
    throw runOptions.deadlineError?.()
      ?? new Error(`verification evidence command deadline exceeded at ${runOptions.deadlineAt}`);
  }
  return {
    executable,
    args,
    code: result.code,
    output: result.output,
    }];
  });
}

/**
 * The batch evidence handler runs at most one child per exact command string.
 * Parse through its shared executable allowlist before deriving an outer budget:
 * a raw shell program or malformed command remains on the ordinary CLI ceiling
 * and never gains a longer watchdog merely by appearing in user input.
 */
function verificationEvidenceBatchDerivedBudget(root: string, args: Record<string, unknown>): TimeoutBudget | null {
  if (!Array.isArray(args.evidences)) return null;
  const distinctCommands = new Map<string, { executable: string; args: string[] }>();
  for (const evidence of args.evidences) {
    if (!evidence || typeof evidence !== 'object') continue;
    const command = (evidence as { command?: unknown }).command;
    if (typeof command !== 'string' || !command.trim()) continue;
    try {
      distinctCommands.set(command.trim(), parseAllowlistedCommand(command));
    } catch {
      // The evidence handler will refuse this same input; do not widen the
      // outer watchdog for a command outside the pinned execution boundary.
    }
  }
  if (distinctCommands.size === 0) return null;
  const overrides = loadConfig(root).validate?.evidenceCommandTimeoutOverrides;
  const commandBudgetMs = safeTimeoutSum([...distinctCommands.values()].map((identity) => (
    resolveEvidenceCommandTimeoutMs(identity, overrides)
  )));
  return {
    timeoutMs: safeTimeoutSum([commandBudgetMs, DEFAULT_TIMEOUT_BUDGET_GRACE_MS]),
    source: 'derived-command-budget',
    commandBudgetMs,
    graceMs: DEFAULT_TIMEOUT_BUDGET_GRACE_MS,
  };
}

/**
 * Compute the exact raw pinned-command keys that a non-dry-run stale refresh
 * will attempt. This deliberately mirrors the handler's pre-lock snapshot:
 * current stale coverage entries only, executable intents with a pin only, and
 * one execution per raw pin command in the resolved story git workspace.
 *
 * It is a read-only best-effort budget probe. Any missing story/git/config state
 * retains the ordinary CLI watchdog instead of changing refresh semantics.
 */
function staleRefreshPinnedCommands(root: string, storyId: string): string[] {
  const store = new StoryStore(root);
  const refreshGitCwd = resolveGitCwd({ store, storyId, metadataRoot: root, projectRoot: root });
  const headHash = currentGitHead(refreshGitCwd);
  if (!headHash) return [];
  const checklist = store.readChecklist(storyId);
  const coverage = buildVerificationCoverage(
    checklist,
    headHash,
    (oldHeadHash, evidence) => checkEvidenceFreshnessForGit(
      refreshGitCwd,
      oldHeadHash,
      evidence?.materialHash,
      root,
      evidence?.storyFilesHash,
    ).fresh,
    { deferredGateEvidence: 'missing' },
  );
  const commands = new Set<string>();
  for (const entry of coverage.entries) {
    if (entry.status !== 'stale' || !entry.evidence) continue;
    const item = checklist.items.find((candidate) => candidate.id === entry.itemId);
    const resolved = item && collectVerificationIntents(item).find((candidate) => candidate.ref === entry.intentRef);
    const pin = resolved?.intent.verification;
    if (!resolved || !pin || !isExecutableIntentType(resolved.intent.type) || typeof pin.command !== 'string') continue;
    commands.add(pin.command);
  }
  return [...commands];
}

/**
 * A stale refresh runs its distinct executable pins serially. Derive the outer
 * watchdog from the exact command set the handler will re-execute, after the
 * same allowlist parse and per-command timeout resolver used by that handler.
 */
function verificationEvidenceRefreshDerivedBudget(root: string, args: Record<string, unknown>): TimeoutBudget | null {
  if (args.dryRun === true) return null;
  const storyId = typeof args.storyId === 'string' ? args.storyId.trim() : '';
  if (!storyId) return null;
  let commands: string[];
  try {
    commands = staleRefreshPinnedCommands(root, storyId);
  } catch {
    return null;
  }
  const distinctCommands = new Map<string, { executable: string; args: string[] }>();
  for (const command of commands) {
    try {
      // The handler deduplicates by the original pin command (with one resolved
      // git cwd per refresh), not by a normalized shell representation.
      distinctCommands.set(command, parseAllowlistedCommand(command));
    } catch {
      // Matching the handler, this pin is refused at execution time. It cannot
      // widen an outer watchdog simply by appearing in stale story metadata.
    }
  }
  if (distinctCommands.size === 0) return null;
  const overrides = loadConfig(root).validate?.evidenceCommandTimeoutOverrides;
  const commandBudgetMs = safeTimeoutSum([...distinctCommands.values()].map((identity) => (
    resolveEvidenceCommandTimeoutMs(identity, overrides)
  )));
  return {
    timeoutMs: safeTimeoutSum([commandBudgetMs, DEFAULT_TIMEOUT_BUDGET_GRACE_MS]),
    source: 'derived-command-budget',
    commandBudgetMs,
    graceMs: DEFAULT_TIMEOUT_BUDGET_GRACE_MS,
  };
}

export function doneRequiredDerivedBudget(root: string): TimeoutBudget {
  const commands = resolveDoneRequiredPolicy(root).commands;
  const commandBudgetMs = safeTimeoutSum(commands.map((command) => resolveCommandTimeoutMs(command)));
  return {
    timeoutMs: safeTimeoutSum([commandBudgetMs, DEFAULT_TIMEOUT_BUDGET_GRACE_MS]),
    source: 'derived-command-budget',
    commandBudgetMs,
    graceMs: DEFAULT_TIMEOUT_BUDGET_GRACE_MS,
  };
}

